fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    // If there are 0 or 1 elements, just return the input unchanged
    if n <= 1 {
        return numbers;
    }

    // Otherwise, we need 2 * n - 1 slots: each original element plus delimiters in between
    let mut result = Vec::with_capacity(2 * n - 1);

    // Always start with the first element
    result.push(numbers[0]);

    // For each remaining element, push a delimiter then the element
    for &num in &numbers[1..] {
        result.push(delimiter);
        result.push(num);
    }

    result
}

